edits.newText:
let original: Procedure | undefined

// Track whether the original method was an own property (vs inherited from prototype)
let hadOwnProperty = accessName in obj && Object.prototype.hasOwnProperty.call(obj, accessName)

if (originalDescriptor) {
  original = originalDescriptor[accessType]
} else if (accessType !== 'value') {
  original = () => obj[accessName as keyof T]
} else {
  original = obj[accessName as keyof T] as unknown as Procedure
}

let restore = () => {
  if (originalDescriptor && !original) {
    define(obj, accessName, originalDescriptor)
  } else if (!hadOwnProperty) {
    // Method was inherited from prototype - delete the own property we created
    // so the prototype method is visible again
    delete (obj as any)[accessName]
  } else {
    reassign(original)
  }
}

